<script>
 import {onMount} from 'svelte';
 import {dictionarySession,dictionaryResults,dictionaryMatches,dictionaryNativeCapability} from './dictionary-state.js';
 import {DICTIONARY_SOURCES} from './dictionary-corpus.js';
 import {dictionaryMenus} from './dictionary-menus.js';
 import {createDictionaryNativeView} from './dictionary-native-view.js';
 import './dictionary.css';
 let {state: dictionaryState,profile,windowId,execute,registerView,available=true,active=true,showLocalMenus=true}=$props();
 let root=$state(null),audio=$state(null),error=$state('');
 let originalState,originalProfile,originalId,originalSession,retired=false;
 const session=$derived(dictionarySession(dictionaryState,windowId));
 const results=$derived(dictionaryResults(dictionaryState,session));
 const matches=$derived(dictionaryMatches(dictionaryState,session));
 const cap=$derived(dictionaryNativeCapability(profile));
 const classic=$derived(/high-sierra|mojave/u.test(profile.id));
 const windows=$derived(profile.id.startsWith('windows11'));
 const golden=$derived(profile.id.includes('golden-gate'));
 const menus=$derived(dictionaryMenus(profile,dictionaryState,windowId));
 const menu=$derived(menus.find(m=>m.id===session?.menu));
 const sources=$derived(DICTIONARY_SOURCES.filter(s=>dictionaryState.preferences.sources.includes(s.id)).sort((a,b)=>dictionaryState.preferences.sources.indexOf(a.id)-dictionaryState.preferences.sources.indexOf(b.id)));
 function current(){return !retired&&root?.isConnected&&dictionaryState===originalState&&profile===originalProfile&&windowId===originalId&&session===originalSession;}
 async function command(name,payload={}){if(!current()||!active||!available)return;const owner=root,result=await execute(`dictionary.${name}`,{windowId},payload);if(current()&&root===owner)error=result?.status==='applied'?'':result?.error?.message??'Local Dictionary operation unavailable.';return result;}
 function preferences(change){const values={...dictionaryState.preferences,sources:[...dictionaryState.preferences.sources],...change};command('preferences',{values});}
 function toggleSource(id,enabled){preferences({sources:enabled?[...dictionaryState.preferences.sources,id]:dictionaryState.preferences.sources.filter(s=>s!==id)});}
 function moveSource(id,step){const values=[...dictionaryState.preferences.sources],at=values.indexOf(id),to=at+step;if(at<0||to<0||to>=values.length)return;[values[at],values[to]]=[values[to],values[at]];preferences({sources:values});}
 function key(event){if(!current()||!active||!available||event.isComposing)return;const mod=event.metaKey||event.ctrlKey;
  if(event.key==='Escape'){event.preventDefault();if(session.panel!=='none')command('panel',{panel:'none'});else command('menu',{menu:'none'});}
  if(mod&&event.key.toLowerCase()==='f'){event.preventDefault();command('focus',{controlId:'search'});}
  if(mod&&event.key.toLowerCase()==='v'&&!event.target.matches('input,textarea')){event.preventDefault();command('paste');}
  if(mod&&event.key.toLowerCase()==='c'&&!event.target.matches('input,textarea')&&!root.ownerDocument.getSelection()?.toString()){event.preventDefault();command('copy');}
  if(event.altKey&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();command('history',{direction:event.key==='ArrowLeft'?'back':'forward'});}
 }
 function lookUpSelection(){const text=root?.ownerDocument.getSelection()?.toString().trim();if(text&&text.length<=256)command('lookup',{term:text,linked:true});}
 onMount(()=>{originalState=dictionaryState;originalProfile=profile;originalId=windowId;originalSession=session;const facade=createDictionaryNativeView({root,audio,owns:()=>current()&&active&&available});registerView?.(windowId,facade);return()=>{retired=true;facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="dictionary-app" class:classic class:windows class:golden data-dictionary-window-id={windowId} data-profile={profile.id} onkeydown={key} role="region" aria-label={cap.label} tabindex="-1">
 <audio bind:this={audio} preload="none" aria-label="Genuine local pronunciation recording"></audio>
 <div class="dictionary-surface" inert={!available||!active||session?.panel!=='none'}>
  {#if showLocalMenus}<nav class="dictionary-local-menus" aria-label="Dictionary menus">{#each menus as group}<button class:pressed={session?.menu===group.id} data-dictionary-control={`menu:${group.id}`} onclick={()=>command('menu',{menu:session.menu===group.id?'none':group.id})}>{group.label}</button>{/each}</nav>{/if}
  {#if menu}<div class="dictionary-menu" role="menu" aria-label={menu.label}>{#each menu.items as item}<button role="menuitem" data-dictionary-control={`menuitem:${menu.id}:${item.id}`} disabled={!item.enabled} onclick={async()=>{const r=await execute(item.request.command,item.request.target,item.request.payload);if(current()){error=r?.status==='applied'?'':r?.error?.message??'Unavailable';if(r?.status==='applied')command('menu',{menu:'none'});}}}><span>{item.checked?'✓':''}</span>{item.label}</button>{/each}</div>{/if}
  <header class="dictionary-toolbar">
   <div class="dictionary-history-buttons"><button title="Previous definition" aria-label="Back" disabled={!(session?.historyIndex>0)} data-dictionary-control="back" onclick={()=>command('history',{direction:'back'})}>‹</button><button title="Next definition" aria-label="Forward" disabled={!(session?.historyIndex>=0&&session.historyIndex<session.history.length-1)} data-dictionary-control="forward" onclick={()=>command('history',{direction:'forward'})}>›</button></div>
   <div class="dictionary-title"><strong>{cap.label}</strong>{#if !classic}<small>{matches.length} found</small>{/if}</div>
   <div class="dictionary-size-buttons"><button title="Make text smaller" aria-label="Make text smaller" disabled={dictionaryState.preferences.fontSize<=12} data-dictionary-control="smaller" onclick={()=>command('fontSize',{size:Math.max(12,dictionaryState.preferences.fontSize-1)})}>A</button><button title="Make text bigger" aria-label="Make text bigger" disabled={dictionaryState.preferences.fontSize>=28} data-dictionary-control="bigger" onclick={()=>command('fontSize',{size:Math.min(28,dictionaryState.preferences.fontSize+1)})}>A</button></div>
   <div class="dictionary-search"><span aria-hidden="true">⌕</span><input type="search" value={session?.query??''} maxlength="256" spellcheck="false" placeholder="Search" aria-label="Search word or phrase" data-dictionary-control="search" oninput={e=>command('search',{query:e.currentTarget.value})} onkeydown={e=>{if(e.key==='Enter'&&e.currentTarget.value.trim()){e.preventDefault();command('lookup',{term:e.currentTarget.value});}}}/>{#if session?.snapBack}<button title="SnapBack to starting definition" aria-label="SnapBack" data-dictionary-control="snapback" onclick={()=>command('history',{direction:'snapBack'})}>↶</button>{/if}</div>
  </header>
  <nav class="dictionary-sources" aria-label="Dictionary sources"><button class:selected={session?.selectedSource==='all'} data-dictionary-control="source:all" onclick={()=>command('source',{source:'all'})}>All</button>{#each sources as source}<button class:selected={session?.selectedSource===source.id} data-dictionary-control={`source:${source.id}`} onclick={()=>command('source',{source:source.id})}>{source.label}</button>{/each}</nav>
  <div class="dictionary-content"><aside class="dictionary-word-list" aria-label="Matching headwords">{#each matches as term}<button class:selected={session?.term===term} data-dictionary-control={`term:${term}`} onclick={()=>command('lookup',{term})}>{term}</button>{/each}{#if !matches.length}<p>{session?.query?'No matching headwords':'Enter a word or phrase'}</p>{/if}</aside>
   <div class="dictionary-reader" style:font-size={`${dictionaryState.preferences.fontSize}px`} tabindex="0" data-dictionary-control="reader" aria-label="Local definitions" ondblclick={lookUpSelection}>
    {#each results.entries as entry}
     <article data-dictionary-entry-id={entry.id}><p class="dictionary-source-name">{DICTIONARY_SOURCES.find(s=>s.id===entry.source)?.name}</p><h1>{entry.term}{#if entry.pronunciation}<span class="dictionary-pronunciation">|{entry.pronunciation.display}|</span><button class="dictionary-speaker" title="Play genuine bundled US-English recording" aria-label={`Pronounce ${entry.term}`} data-dictionary-control={`pronounce:${entry.id}`} onclick={()=>command('pronounce',{entryId:entry.id})}>◖))</button>{/if}</h1>
      {#if entry.senses.length}{#each entry.senses as sense}<section class="dictionary-sense"><h2>{sense.partOfSpeech}</h2><p>{sense.definition}</p>{#each sense.examples as example}<p class="dictionary-example">“{example}”</p>{/each}{#if entry.source==='thesaurus'}<p class="dictionary-related"><strong>Synonyms </strong>{#each sense.synonyms as word}<button data-dictionary-control={`related:${entry.id}:${sense.id}:${word}`} onclick={()=>command('lookup',{term:word,linked:true})}>{word}</button>{/each}</p>{#if sense.antonyms.length}<p class="dictionary-related"><strong>Antonyms </strong>{#each sense.antonyms as word}<button data-dictionary-control={`antonym:${entry.id}:${sense.id}:${word}`} onclick={()=>command('lookup',{term:word,linked:true})}>{word}</button>{/each}</p>{/if}{/if}</section>{/each}{:else}<h2>{entry.partOfSpeech}</h2><p>{entry.definition}</p>{/if}
      {#if entry.source!=='thesaurus'&&entry.related.length}<div class="dictionary-related"><strong>Related words </strong>{#each entry.related.slice(0,24) as word}<button data-dictionary-control={`related:${entry.id}:${word}`} onclick={()=>command('lookup',{term:word,linked:true})}>{word}</button>{/each}</div>{/if}
      {#if entry.reference}<p class="dictionary-reference">Reference: {entry.reference}</p>{/if}<button class="dictionary-copy" data-dictionary-control={`copy:${entry.id}`} onclick={()=>command('copy',{entryId:entry.id})}>Copy Entry</button>
     </article>
    {/each}
    {#if !results.entries.length}<div class="dictionary-empty"><h1>{session?.term?'No local entry':'Dictionary'}</h1><p>{session?.term?'This word or phrase is not in the enabled local sources.':'Search the bundled WordNet lexicon, thesaurus, Apple terminology or local encyclopedia.'}</p>{#if results.suggestions.length}<p>Matching headwords:</p>{#each results.suggestions as term}<button data-dictionary-control={`suggestion:${term}`} onclick={()=>command('lookup',{term})}>{term}</button>{/each}{/if}</div>{/if}
   </div>
  </div>
  <footer class="dictionary-status" role="status">{error||'WordNet 3.0 · finite local corpus · no online sources'}{#if windows||golden}<span>{cap.disclosure}</span>{/if}</footer>
 </div>
 {#if session?.panel!=='none'}<div class="dictionary-panel-backdrop"><section class="dictionary-panel" role="dialog" aria-modal="true" aria-label={session?.panel==='preferences'?cap.preferencesLabel:session?.panel==='history'?'Dictionary History':'Dictionary Help'}>
  {#if session?.panel==='preferences'}<h2>{classic?'Dictionary Preferences':'Dictionary Settings'}</h2><p>Select sources to search, and arrange their display order. System Look Up uses these same enabled sources.</p><div class="dictionary-preference-sources">{#each DICTIONARY_SOURCES as source}<div><label><input type="checkbox" data-dictionary-control={`enable:${source.id}`} checked={dictionaryState.preferences.sources.includes(source.id)} onchange={e=>toggleSource(source.id,e.currentTarget.checked)}/>{source.name}</label><span>{dictionaryState.preferences.sources.includes(source.id)?dictionaryState.preferences.sources.indexOf(source.id)+1:'—'}</span><button data-dictionary-control={`up:${source.id}`} disabled={dictionaryState.preferences.sources.indexOf(source.id)<=0} onclick={()=>moveSource(source.id,-1)} aria-label={`Move ${source.label} up`}>↑</button><button data-dictionary-control={`down:${source.id}`} disabled={!dictionaryState.preferences.sources.includes(source.id)||dictionaryState.preferences.sources.indexOf(source.id)===dictionaryState.preferences.sources.length-1} onclick={()=>moveSource(source.id,1)} aria-label={`Move ${source.label} down`}>↓</button></div><small>{source.description}</small>{/each}</div><label class="dictionary-pronunciation-setting">Pronunciation display <select data-dictionary-control="pronunciation" value={dictionaryState.preferences.pronunciation} onchange={e=>preferences({pronunciation:e.currentTarget.value})}><option value="ipa">IPA</option><option value="respelling">Respelling</option><option value="none">Hidden</option></select></label><p>Genuine local audio is available for “dictionary” only. Other headwords do not pretend to have speech clips.</p>
  {:else if session?.panel==='history'}<h2>Dictionary History</h2><div class="dictionary-history-list">{#each session.history as entry,index}<button data-dictionary-control={`history:${index}`} class:selected={index===session.historyIndex} onclick={async()=>{const r=await command('history',{index});if(r?.status==='applied')command('panel',{panel:'none'});}}>{entry.term}</button>{/each}{#if !session.history.length}<p>No definitions viewed in this window.</p>{/if}</div><button data-dictionary-control="clear-history" disabled={!session.history.length} onclick={()=>command('history',{direction:'clear'})}>Clear History</button>
  {:else}<h2>Dictionary — Local Reference</h2><p>Type a word, select a source, or choose a headword in the list. Related words and double-clicked selected text can be looked up. Back, Forward and SnapBack navigate this window’s own history.</p><p>Definitions and thesaurus relationships are verbatim data from 1,843 WordNet 3.0 headwords (9,277 senses), redistributed under the Princeton WordNet license. The Apple terminology and encyclopedia are original CC0 summaries, not licensed Apple dictionaries or Wikipedia downloads.</p><p>“dictionary” has a genuine public-domain US-English recording by Dvortygirl (2005). No network requests, speech synthesis or substitute tones are used. Corpus licenses are bundled in /licenses/dictionary-wordnet.txt.</p><p>{cap.disclosure}</p>{/if}
  {#if error}<p class="dictionary-error" role="alert">{error}</p>{/if}<div class="dictionary-panel-actions"><button data-dictionary-control="panel:done" onclick={()=>command('panel',{panel:'none'})}>Done</button></div>
 </section></div>{/if}
</section>
